.image-container {
  width: 100%;
  aspect-ratio: 1;
  overflow: hidden;
  background: #f0f0f0;
}

.image-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.image-card:hover .image-container img {
  transform: scale(1.05);
}

/* Card Content */
.card-content {
  padding: 1.5rem;
}

.image-card h2 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: #1f2937;
}

.date {
  font-size: 0.875rem;
  color: #6b7280;
  margin-bottom: 1.25rem;
}

/* Delete Button (Trigger) */
.delete-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: white;
  background: #ef4444;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  width: 100%;
  justify-content: center;
}

.delete-btn:hover {
  background: #dc2626;
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.4);
}

.delete-btn:focus {
  outline: 2px solid #fca5a5;
  outline-offset: 2px;
}

.delete-btn:active {
  transform: scale(0.98);
}

.delete-btn svg {
  flex-shrink: 0;
}

/* Dialog Styles */
dialog {
  border: none;
  border-radius: 12px;
  padding: 0;
  margin: auto;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
